# Production Domain Services Engine (Python)
import math

def process_domain_logic_step_00001(user_skills, score_val):
    val = len(user_skills) * 1.5 + 1
    if score_val > 0:
        calc = math.sqrt(val) + score_val * 0.2
        if calc > 100.0:
            return round(calc % 100.0, 4)
        else:
            return round(calc, 4)
    else:
        return round(val * 0.5, 4)

